1	// The auto-merge policy engine (docs/PRINCIPLES.md): may THIS diff land
2	// without a person? A task declares `automerge` — `'nothing'`, `'anything'`,
3	// or a list of named diff classes — and this module turns that declaration plus
4	// the branch's actual diff into a verdict. The call is arithmetic over the diff,
5	// never the session's opinion of its own work: a run cannot talk its way past a
6	// text comparison (the narrow-diff posture, generalized).
7	//
8	// WHAT A POLICY IS FOR. A policy is its author's PREDICTION of the change's
9	// shape — the folders and the kinds of file a request should touch. When the
10	// diff sits inside the prediction, nobody reads it: the code is out the door and
11	// working, and a later PR can improve it. When the diff misses the prediction,
12	// the PR parks for a person, and that park is the mechanism's purpose rather
13	// than its failure. The reviewer here is not checking that the code is perfect;
14	// they are checking the wagon is on the trail — that nothing irreversible
15	// slipped through, and that the change's footprint matches its ask (a wide diff
16	// for a small request is a lesson in separation of concerns, not a defect). So a
17	// policy is written narrow, from the predicted folders, and is never widened to
18	// fit the diff that arrived.
19	//
20	// THE VOCABULARY IS EXTENSIBLE AS DATA. Built-in diff classes live here; a pack
21	// adds its own by shipping a `merge-rules.json` beside its `pack.mjs` — named
22	// path/kind/edit-shape matchers, validated at load, colliding loudly. A policy
23	// then names any rule, built-in or declared, plus the inline `under:<dir>` scope
24	// that carries its own argument, and an unknown name FAILS CLOSED: a policy this
25	// code cannot fully resolve authorizes nothing.
26	//
27	// A LIST IS A UNION, `&&` IS THE INTERSECTION. Listing two terms widens — each
28	// changed file need only be covered by one of them — so the way to say "docs,
29	// but only under this folder" is one `&&` term, never two list entries.
30	//
31	// POLICY SEMANTICS, in evaluation order:
32	//   - `'nothing'`  — never mergeable. `'anything'` — mergeable (the repo's own
33	//     delivery settings still apply downstream, land-pr.mjs).
34	//   - a LIST mixes allow terms and `reject:<name>` terms. A reject matching any
35	//     changed file vetoes the whole diff; otherwise every changed file must be
36	//     covered by some allow term (first listed match wins), and every matched
37	//     rule's whole-diff constraint (e.g. "one code directory") must hold. A list
38	//     with no allow term is an authoring error, not "anything except" — spell
39	//     that as `['anything', 'reject:<name>']`.
40	//   - THE SELF-WIDENING GUARD: under a list policy, a change to the files that
41	//     define policies (`merge-rules.json`, `tasks/<name>/task.json`, this module,
42	//     its work-scope gate) is never coverable unless it is comment-only — a run
43	//     must not be able to grant itself a wider authorization than it started
44	//     with. Only the plain `'anything'` (the trusted lane: the vendored-mount
45	//     converge) can land such a change.
46	//
47	// Two judging surfaces read one resolution path: the landing lane's CLI below
48	// (what the worker doc tells a run to execute before it may merge), and the
49	// `automerge-policy-scope` work check beside this file, which re-evaluates the
50	// same verdict over a branch that stamped the arming trailer.
51	
52	import path from 'node:path';
53	import { readFileSync, existsSync } from 'node:fs';
54	import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';
55	import { FILE_CLASSES } from '../../../../engine/checks/helpers/pattern-rules.mjs';
56	import { isActive } from '../../../../engine/pack_loader/pack-registry.mjs';
57	import { AUTOMERGE_TRAILER } from '../../public/task-constants.mjs';
58	
59	export { COMMENT_CHECKABLE, commentOnly };
60	
61	export const POLICY_NOTHING = 'nothing';
62	export const POLICY_ANYTHING = 'anything';
63	
64	// The commit-message trailer a run stamps when it intends to land its own PR
65	// under a granular policy — what makes the work-scope gate self-gating: no
66	// trailer, no armed auto-merge, nothing to judge. The policy expression is the
67	// string form below (`a;b;reject:c`).
68	export { AUTOMERGE_TRAILER };
69	export const AUTOMERGE_TRAILER_RE = /^Claudinite-Automerge-Policy:[ \t]*(\S+)[ \t]*$/m;
70	
71	// --- path classification (shared with narrow-diff.mjs, which re-exports it) ---
72	
73	const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);
74	
75	const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);
76	
77	// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
78	// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
79	// not a test directory; file names are matched on the conventions every ecosystem
80	// here shares.
81	export function classifyPath(file) {
82	  const segments = file.split('/');
83	  const name = segments[segments.length - 1];
84	  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
85	  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
86	  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
87	  return 'code';
88	}
89	
90	// --- diff entries -------------------------------------------------------------
91	
92	// One changed file with both contents: null `before` = added, null `after` =
93	// deleted. Everything below judges these, so a caller with another diff source
94	// (the work-scope context) builds the same shape.
95	export const changeKindOf = ({ before, after }) =>
96	  (before == null ? 'added' : after == null ? 'deleted' : 'modified');
97	
98	// Only line removals (and nothing else): the after-lines are an ordered
99	// subsequence of the before-lines. Deliberately order-preserving — a reorder is
100	// an edit, not a removal — and a whole-file deletion is every line removed.
101	export function removalsOnly(before, after) {
102	  return shrinkOnly(before, after, (line, original) => line === original);
103	}
104	
105	// Removals, plus in-line TRIMS: every surviving line either equals a line it
106	// replaces or is a character-subsequence of one — a line cut in half, a word
107	// struck from its middle, a truncation closed with a period the original
108	// already held. What can never pass is growth: no new line, and no character a
109	// replaced line did not already carry in order. The alignment is greedy and
110	// backtrack-free, so a pathological reshuffle can read as not-a-trim — that
111	// end fails safe (the diff parks for review).
112	export function trimsOnly(before, after) {
113	  return shrinkOnly(before, after, isCharSubsequence);
114	}
115	
116	function shrinkOnly(before, after, lineSatisfies) {
117	  if (after == null) return true;
118	  if (before == null) return false;
119	  const from = before.split('\n');
120	  const to = after.split('\n');
121	  let i = 0;
122	  for (const line of to) {
123	    while (i < from.length && !lineSatisfies(line, from[i])) i += 1;
124	    if (i === from.length) return false;
125	    i += 1;
126	  }
127	  return true;
128	}
129	
130	function isCharSubsequence(needle, hay) {
131	  let i = 0;
132	  for (const c of needle) {
133	    i = hay.indexOf(c, i);
134	    if (i === -1) return false;
135	    i += 1;
136	  }
137	  return true;
138	}
139	
140	const isCommentOnlyChange = (e) => changeKindOf(e) === 'modified' && commentOnly(e.file, e.before, e.after);
141	
142	// --- the rule registry --------------------------------------------------------
143	// A rule is `{ name, appliesTo(entry) }` plus, for the whole-diff rules, a
144	// `constraint(coveredEntries)` returning null or the reason it fails. `appliesTo`
145	// answers both roles a policy can use the name in: as an allow term it covers the
146	// files it applies to, as a `reject:` term it vetoes on them.
147	
148	// The two code-locality rules deliberately do NOT apply to a comment-only code
149	// file (mirroring narrowVerdict): a comment edit is `comment-only-changes`'
150	// business, and counting it toward the file/directory budget would fail a diff
151	// the policy's author plainly meant to allow.
152	const isRealCodeChange = (e) => classifyPath(e.file) === 'code' && !isCommentOnlyChange(e);
153	
154	export const BUILTIN_MERGE_RULES = new Map([
155	  ['doc-changes', {
156	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && classifyPath(e.file) === 'doc',
157	  }],
158	  ['readme-changes', {
159	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).toLowerCase() === 'readme.md',
160	  }],
161	  ['comment-only-changes', {
162	    appliesTo: isCommentOnlyChange,
163	  }],
164	  // Every change kind, a deletion included: a policy naming this class predicted
165	  // the test tree as the change's shape, and a test file removed or renamed
166	  // inside that tree is that same shape — a rename lands as a delete beside an
167	  // add, and parking it asked a reviewer for a decision nobody made.
168	  ['test-changes', {
169	    appliesTo: (e) => classifyPath(e.file) === 'test',
170	  }],
171	  ['markdown-line-removals', {
172	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
173	      && changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after),
174	  }],
175	  // The trim superset of the rule above: whole-line removals plus in-line trims
176	  // (trimsOnly) — for a prune allowed to cut a line down, never to grow one.
177	  ['markdown-trims', {
178	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
179	      && changeKindOf(e) !== 'added' && trimsOnly(e.before, e.after),
180	  }],
181	  ['file-additions', {
182	    appliesTo: (e) => changeKindOf(e) === 'added',
183	  }],
184	  ['generated-file-changes', {
185	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).includes('GENERATED'),
186	  }],
187	  // The language-scoped class, matching ANY change to a JavaScript-family file —
188	  // built in mostly for its `reject:` use ("nothing may touch the JS"), which is
189	  // why it applies to every change kind. Its file set is the checks engine's own
190	  // JavaScript class, so the two surfaces cannot disagree on what counts.
191	  ['javascript-changes', {
192	    appliesTo: (e) => FILE_CLASSES.javascriptFiles.test(e.file),
193	  }],
194	  ['single-file-code-changes', {
195	    appliesTo: isRealCodeChange,
196	    constraint: (covered) => {
197	      const files = [...new Set(covered.map((e) => e.file))].sort();
198	      return files.length <= 1 ? null : `code changed in ${files.length} files: ${files.join(', ')}`;
199	    },
200	  }],
201	  ['single-folder-code-changes', {
202	    appliesTo: isRealCodeChange,
203	    constraint: (covered) => {
204	      const dirs = [...new Set(covered.map((e) => path.dirname(e.file)))].sort();
205	      return dirs.length <= 1 ? null : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`;
206	    },
207	  }],
208	]);
209	
210	// Composites expand into their member allow terms — `narrow-diff` is the queue's
211	// historical `Merge: if-narrow` shape. Slightly stricter than the retired
212	// narrowVerdict on purpose: a DELETED doc is no longer silently allowed
213	// (deciding a document should not exist is a reviewed change — the
214	// improve-comments-scope lesson), which fails toward a parked PR, never a merge.
215	export const COMPOSITE_POLICIES = new Map([
216	  ['narrow-diff', ['doc-changes', 'test-changes', 'comment-only-changes', 'single-folder-code-changes']],
217	]);
218	
219	// --- the inline path scope (`under:<dir>`) ------------------------------------
220	
221	// A rule name that carries its own argument: `under:packs/claudinite-tasks`
222	// covers every change inside that directory. It exists because a scope is
223	// usually per-request — the one folder an ad-hoc ask or a task is confined to —
224	// where a named merge-rules.json rule is per-pack and costs a commit to add.
225	//
226	// It covers any change KIND inside the directory (added, modified, deleted):
227	// "any change under this folder" reads as literally any. And it scopes rather
228	// than widens — a changed file outside the folder is covered by no allow term,
229	// so a diff that strays parks — with POLICY_SOURCES below still absolute, so a
230	// folder scope cannot reach the files that define policies even when they sit
231	// inside it.
232	export const UNDER_PREFIX = 'under:';
233	
234	const PATH_SEGMENT_RE = /^[A-Za-z0-9._-]+$/;
235	
236	// The rule an `under:<dir>` term denotes, or null when `<dir>` is not a usable
237	// repo-relative directory (absolute, empty, or carrying a `.`/`..` segment).
238	// Null is a verdict: an unresolvable scope makes the whole policy invalid, which
239	// authorizes nothing — the same fail-closed answer an unknown rule name gets.
240	export function underRule(term) {
241	  const dir = term.slice(UNDER_PREFIX.length).replace(/\/+$/, '');
242	  const segments = dir.split('/');
243	  if (!dir || segments.some((seg) => !PATH_SEGMENT_RE.test(seg) || seg === '.' || seg === '..')) return null;
244	  const prefix = `${dir}/`;
245	  return { name: term, appliesTo: (e) => e.file.startsWith(prefix) };
246	}
247	
248	// --- the `&&` intersection ----------------------------------------------------
249	
250	// A policy list is a UNION: adding a term widens what may land. `&&` is the one
251	// narrowing operator — `under:product-wiki&&doc-changes` covers a file only when
252	// every part covers it, so it reads as "docs, and only under that folder".
253	//
254	// Whitespace around it is accepted wherever a human writes one (an issue's
255	// `Automerge:` line, a task declaration) and canonicalized away by
256	// `policyExpression`, so what rides the commit trailer stays one whitespace-free
257	// token. `&` is not a legal character in a rule name or an `under:` path, so the
258	// operator can never be read as part of a term.
259	export const CONJUNCTION = '&&';
260	
261	const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());
262	
263	// --- pack-declared rules (merge-rules.json) -----------------------------------
264	
265	export const MERGE_RULES_FILE = 'merge-rules.json';
266	
267	const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
268	const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
269	const CHANGE_KINDS = ['added', 'modified', 'deleted'];
270	const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];
271	
272	// Regex-as-string in the `/body/flags` form declared-checks.json already uses —
273	// the same inline parse pattern-rules.mjs applies (this module cannot import the
274	// checks engine's private compiler, so the six lines live here and point there).
275	function compileRegex(raw, where) {
276	  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
277	  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
278	  return new RegExp(m[1], m[2]);
279	}
280	
281	// One declared rule compiled into the registry shape. Every key is validated and
282	// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
283	// a matcher nobody decided (the corpus' explicit-over-default rule).
284	export function compileDeclaredRule(spec, where) {
285	  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
286	    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
287	  }
288	  for (const key of Object.keys(spec)) {
289	    if (!DECLARED_KEYS.includes(key)) {
290	      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
291	    }
292	  }
293	  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
294	    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
295	  }
296	  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
297	  const exclude = spec.excludePathMatching === undefined
298	    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
299	  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
300	      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
301	    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
302	  }
303	  if (!EDIT_SHAPES.includes(spec.editShape)) {
304	    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
305	  }
306	  // The one key that may relax the self-widening guard, and only for files under
307	  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
308	  // saying "this task may rewrite the mount, policy definitions included" — the
309	  // adoption/converge grant. `true` only, so it cannot be half-declared.
310	  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
311	    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
312	  }
313	  return {
314	    name: spec.name,
315	    coversMountPolicySources: spec.coversMountPolicySources === true,
316	    appliesTo(e) {
317	      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
318	      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
319	      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
320	      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
321	      return true;
322	    },
323	  };
324	}
325	
326	// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
327	// pack objects (each with `.dir`), `config` the normalized repo config — the pair
328	// both judging surfaces already hold. A broken declaration or a name collision is
329	// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
330	// closed, and the error text is what gets it fixed.
331	export function declaredMergeRules(packs, config) {
332	  const rules = new Map();
333	  const errors = [];
334	  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
335	    const file = path.join(pack.dir, MERGE_RULES_FILE);
336	    if (!existsSync(file)) continue;
337	    const where = `${pack.id}/${MERGE_RULES_FILE}`;
338	    let specs;
339	    try {
340	      specs = JSON.parse(readFileSync(file, 'utf8'));
341	      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
342	    } catch (e) {
343	      errors.push(`${where}: ${e.message}`);
344	      continue;
345	    }
346	    for (const spec of specs) {
347	      try {
348	        const rule = compileDeclaredRule(spec, where);
349	        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
350	          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
351	        }
352	        rules.set(rule.name, rule);
353	      } catch (e) {
354	        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
355	      }
356	    }
357	  }
358	  return { rules, errors };
359	}
360	
361	// --- policy parsing -----------------------------------------------------------
362	
363	const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;
364	
365	// A policy, normalized from any surface it rides — the declaration's string or
366	// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
367	// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
368	// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
369	// every consumer treats it as "authorizes nothing", loudly.
370	export function normalizePolicy(raw) {
371	  if (raw == null) return { kind: POLICY_NOTHING };
372	  const terms = Array.isArray(raw)
373	    ? raw.map((t) => String(t).trim())
374	    : String(raw).trim().split(';').map((t) => t.trim());
375	  if (terms.length === 1) {
376	    const one = terms[0].toLowerCase();
377	    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
378	    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
379	    // The queue's historical spellings for its one pre-policy authorization.
380	    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
381	  }
382	  const allow = [];
383	  const reject = [];
384	  for (const term of terms) {
385	    const isReject = term.startsWith('reject:');
386	    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
387	    for (const part of parts) {
388	      if (!TERM_NAME_RE.test(part)) {
389	        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
390	      }
391	      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
392	        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
393	      }
394	    }
395	    // A composite is itself a union, so intersecting one is ambiguous, and the
396	    // whole-policy words mean nothing narrowed: both are authoring errors.
397	    if (parts.length > 1) {
398	      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
399	      if (notIntersectable) {
400	        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
401	      }
402	    }
403	    const name = parts.join(CONJUNCTION);
404	    if (isReject) {
405	      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
406	      reject.push(name);
407	    } else if (name === POLICY_ANYTHING) {
408	      allow.push(name);
409	    } else if (name === POLICY_NOTHING) {
410	      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
411	    } else {
412	      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
413	    }
414	  }
415	  if (!allow.length) {
416	    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
417	  }
418	  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
419	}
420	
421	// The string form of a declared policy — what rides the commit trailer and the
422	// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
423	// the one place whitespace around `&&` is collapsed, which is what keeps the
424	// stamped trailer a single whitespace-free token.
425	export const policyExpression = (policy) =>
426	  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
427	    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
428	    .join(';');
429	
430	// --- the verdict --------------------------------------------------------------
431	
432	// The files no granular policy may cover except as comment-only edits: the
433	// sources the policy machinery itself is read from. Whatever an allow rule says,
434	// a run authorized by a list must not be able to rewrite what it is authorized
435	// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
436	// the mount refresh replaces these files wholesale, and that lane's trust is the
437	// repo's delivery setting, not a diff class.)
438	//
439	// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
440	// a declared rule carrying `coversMountPolicySources` — the shape an adoption
441	// re-vendor has, where policy files arrive canon-authored inside the pack trees
442	// it copies. The flag rides merge-rules.json, which is itself guarded and
443	// owner-committed, so a run cannot grant it to itself; repo-owned policy
444	// sources (everything outside the mount) stay absolute.
445	const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.json)$/;
446	const VENDORED_MOUNT = /^\.claudinite\/shared\//;
447	
448	// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
449	// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
450	// `errors` passed through so a broken declaration fails any policy that names
451	// the broken pack's rule set. Returns { mergeable, why, files, problems }:
452	// `files` carries one line per changed file (its covering rule, or its
453	// violation), `problems` each refusal as { file, what } — file null for a
454	// whole-diff refusal — because a run that parks has to say what it parked over.
455	export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
456	  const refuse = (problems, files = []) => ({
457	    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
458	  });
459	  const norm = normalizePolicy(policy);
460	  if (norm.kind === 'invalid') return refuse([{ file: null, what: `invalid policy: ${norm.reason}` }]);
461	  if (norm.kind === POLICY_NOTHING) {
462	    return refuse([{ file: null, what: 'the policy authorizes nothing to auto-merge' }]);
463	  }
464	  if (norm.kind === POLICY_ANYTHING) {
465	    return { mergeable: true, why: 'the policy authorizes any diff (the repo\'s delivery settings still apply)', files: [], problems: [] };
466	  }
467	  if (!entries.length) {
468	    return refuse([{ file: null, what: 'this branch changes nothing against the base — there is nothing to merge' }]);
469	  }
470	
471	  const resolveOne = (name) => (name.startsWith(UNDER_PREFIX)
472	    ? underRule(name)
473	    : BUILTIN_MERGE_RULES.get(name) ?? declaredRules.get(name) ?? null);
474	  // An `&&` term is one rule that every part must agree on — for coverage and
475	  // for the whole-diff constraints alike. It deliberately carries no
476	  // `coversMountPolicySources`: that grant belongs to the declared rule that was
477	  // committed with it, never to an expression composed around it.
478	  const resolve = (name) => {
479	    if (!name.includes(CONJUNCTION)) return resolveOne(name);
480	    const parts = name.split(CONJUNCTION).map(resolveOne);
481	    if (parts.some((r) => !r)) return null;
482	    return {
483	      name,
484	      appliesTo: (e) => parts.every((r) => r.appliesTo(e)),
485	      constraint: (covered) => parts.map((r) => r.constraint?.(covered) ?? null).find(Boolean) ?? null,
486	    };
487	  };
488	  const unknown = [...norm.allow, ...norm.reject].filter((n) => n !== POLICY_ANYTHING && !resolve(n));
489	  if (unknown.length) {
490	    const errs = ruleErrors.length ? ` (rule declarations also failed to load: ${ruleErrors.join('; ')})` : '';
491	    return refuse([{ file: null, what: `unresolved rule name(s): ${unknown.join(', ')} — an unknown rule authorizes nothing${errs}` }]);
492	  }
493	
494	  const files = [];
495	  const problems = [];
496	  const coveredBy = new Map(); // allow name -> entries it covered
497	  for (const entry of entries) {
498	    const { file } = entry;
499	    if (POLICY_SOURCES.test(file) && !isCommentOnlyChange(entry)) {
500	      const mountCoverer = VENDORED_MOUNT.test(file)
501	        && norm.allow.find((n) => resolve(n)?.coversMountPolicySources && resolve(n).appliesTo(entry));
502	      if (!mountCoverer) {
503	        files.push({ file, verdict: 'policy-source' });
504	        problems.push({ file, what: `${file} defines auto-merge policy itself — no granular policy may change it` });
505	        continue;
506	      }
507	      // Exempted: it falls through to the ordinary reject/coverage flow below,
508	      // so a reject term still vetoes it and the flagged rule still has to
509	      // cover it on its own terms.
510	    }
511	    const rejectedBy = norm.reject.find((n) => resolve(n).appliesTo(entry));
512	    if (rejectedBy) {
513	      files.push({ file, verdict: `rejected:${rejectedBy}` });
514	      problems.push({ file, what: `${file} matches reject:${rejectedBy}` });
515	      continue;
516	    }
517	    const coverer = norm.allow.find((n) => n === POLICY_ANYTHING || resolve(n).appliesTo(entry));
518	    if (coverer === undefined) {
519	      files.push({ file, verdict: 'uncovered' });
520	      problems.push({ file, what: `${file} (${changeKindOf(entry)} ${classifyPath(entry.file)}) is covered by no allow term` });
521	      continue;
522	    }
523	    files.push({ file, verdict: `covered:${coverer}` });
524	    if (!coveredBy.has(coverer)) coveredBy.set(coverer, []);
525	    coveredBy.get(coverer).push(entry);
526	  }
527	  for (const [name, covered] of coveredBy) {
528	    const failed = resolve(name)?.constraint?.(covered) ?? null;
529	    if (failed) problems.push({ file: null, what: `${name}: ${failed}` });
530	  }
531	
532	  return problems.length
533	    ? refuse(problems, files)
534	    : { mergeable: true, why: `every changed file is covered (${[...coveredBy.keys()].join(', ')})`, files, problems: [] };
535	}
536	
537	// --- the diff against a base ref (shared with narrow-diff.mjs) ----------------
538	
539	// `stderr: ignore` because the ONE expected failure here — `git show` on a path
540	// that does not exist at that ref — is how an added or deleted file answers, and
541	// letting git narrate it once per such file buries the verdict the caller reads.
542

file.content:
// The auto-merge policy engine (docs/PRINCIPLES.md): may THIS diff land
// without a person? A task declares `automerge` — `'nothing'`, `'anything'`,
// or a list of named diff classes — and this module turns that declaration plus
// the branch's actual diff into a verdict. The call is arithmetic over the diff,
// never the session's opinion of its own work: a run cannot talk its way past a
// text comparison (the narrow-diff posture, generalized).
//
// WHAT A POLICY IS FOR. A policy is its author's PREDICTION of the change's
// shape — the folders and the kinds of file a request should touch. When the
// diff sits inside the prediction, nobody reads it: the code is out the door and
// working, and a later PR can improve it. When the diff misses the prediction,
// the PR parks for a person, and that park is the mechanism's purpose rather
// than its failure. The reviewer here is not checking that the code is perfect;
// they are checking the wagon is on the trail — that nothing irreversible
// slipped through, and that the change's footprint matches its ask (a wide diff
// for a small request is a lesson in separation of concerns, not a defect). So a
// policy is written narrow, from the predicted folders, and is never widened to
// fit the diff that arrived.
//
// THE VOCABULARY IS EXTENSIBLE AS DATA. Built-in diff classes live here; a pack
// adds its own by shipping a `merge-rules.json` beside its `pack.mjs` — named
// path/kind/edit-shape matchers, validated at load, colliding loudly. A policy
// then names any rule, built-in or declared, plus the inline `under:<dir>` scope
// that carries its own argument, and an unknown name FAILS CLOSED: a policy this
// code cannot fully resolve authorizes nothing.
//
// A LIST IS A UNION, `&&` IS THE INTERSECTION. Listing two terms widens — each
// changed file need only be covered by one of them — so the way to say "docs,
// but only under this folder" is one `&&` term, never two list entries.
//
// POLICY SEMANTICS, in evaluation order:
//   - `'nothing'`  — never mergeable. `'anything'` — mergeable (the repo's own
//     delivery settings still apply downstream, land-pr.mjs).
//   - a LIST mixes allow terms and `reject:<name>` terms. A reject matching any
//     changed file vetoes the whole diff; otherwise every changed file must be
//     covered by some allow term (first listed match wins), and every matched
//     rule's whole-diff constraint (e.g. "one code directory") must hold. A list
//     with no allow term is an authoring error, not "anything except" — spell
//     that as `['anything', 'reject:<name>']`.
//   - THE SELF-WIDENING GUARD: under a list policy, a change to the files that
//     define policies (`merge-rules.json`, `tasks/<name>/task.json`, this module,
//     its work-scope gate) is never coverable unless it is comment-only — a run
//     must not be able to grant itself a wider authorization than it started
//     with. Only the plain `'anything'` (the trusted lane: the vendored-mount
//     converge) can land such a change.
//
// Two judging surfaces read one resolution path: the landing lane's CLI below
// (what the worker doc tells a run to execute before it may merge), and the
// `automerge-policy-scope` work check beside this file, which re-evaluates the
// same verdict over a branch that stamped the arming trailer.

import path from 'node:path';
import { readFileSync, existsSync } from 'node:fs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';
import { FILE_CLASSES } from '../../../../engine/checks/helpers/pattern-rules.mjs';
import { isActive } from '../../../../engine/pack_loader/pack-registry.mjs';
import { AUTOMERGE_TRAILER } from '../../public/task-constants.mjs';

export { COMMENT_CHECKABLE, commentOnly };

export const POLICY_NOTHING = 'nothing';
export const POLICY_ANYTHING = 'anything';

// The commit-message trailer a run stamps when it intends to land its own PR
// under a granular policy — what makes the work-scope gate self-gating: no
// trailer, no armed auto-merge, nothing to judge. The policy expression is the
// string form below (`a;b;reject:c`).
export { AUTOMERGE_TRAILER };
export const AUTOMERGE_TRAILER_RE = /^Claudinite-Automerge-Policy:[ \t]*(\S+)[ \t]*$/m;

// --- path classification (shared with narrow-diff.mjs, which re-exports it) ---

const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);

const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);

// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
// not a test directory; file names are matched on the conventions every ecosystem
// here shares.
export function classifyPath(file) {
  const segments = file.split('/');
  const name = segments[segments.length - 1];
  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
  return 'code';
}

// --- diff entries -------------------------------------------------------------

// One changed file with both contents: null `before` = added, null `after` =
// deleted. Everything below judges these, so a caller with another diff source
// (the work-scope context) builds the same shape.
export const changeKindOf = ({ before, after }) =>
  (before == null ? 'added' : after == null ? 'deleted' : 'modified');

// Only line removals (and nothing else): the after-lines are an ordered
// subsequence of the before-lines. Deliberately order-preserving — a reorder is
// an edit, not a removal — and a whole-file deletion is every line removed.
export function removalsOnly(before, after) {
  return shrinkOnly(before, after, (line, original) => line === original);
}

// Removals, plus in-line TRIMS: every surviving line either equals a line it
// replaces or is a character-subsequence of one — a line cut in half, a word
// struck from its middle, a truncation closed with a period the original
// already held. What can never pass is growth: no new line, and no character a
// replaced line did not already carry in order. The alignment is greedy and
// backtrack-free, so a pathological reshuffle can read as not-a-trim — that
// end fails safe (the diff parks for review).
export function trimsOnly(before, after) {
  return shrinkOnly(before, after, isCharSubsequence);
}

function shrinkOnly(before, after, lineSatisfies) {
  if (after == null) return true;
  if (before == null) return false;
  const from = before.split('\n');
  const to = after.split('\n');
  let i = 0;
  for (const line of to) {
    while (i < from.length && !lineSatisfies(line, from[i])) i += 1;
    if (i === from.length) return false;
    i += 1;
  }
  return true;
}

function isCharSubsequence(needle, hay) {
  let i = 0;
  for (const c of needle) {
    i = hay.indexOf(c, i);
    if (i === -1) return false;
    i += 1;
  }
  return true;
}

const isCommentOnlyChange = (e) => changeKindOf(e) === 'modified' && commentOnly(e.file, e.before, e.after);

// --- the rule registry --------------------------------------------------------
// A rule is `{ name, appliesTo(entry) }` plus, for the whole-diff rules, a
// `constraint(coveredEntries)` returning null or the reason it fails. `appliesTo`
// answers both roles a policy can use the name in: as an allow term it covers the
// files it applies to, as a `reject:` term it vetoes on them.

// The two code-locality rules deliberately do NOT apply to a comment-only code
// file (mirroring narrowVerdict): a comment edit is `comment-only-changes`'
// business, and counting it toward the file/directory budget would fail a diff
// the policy's author plainly meant to allow.
const isRealCodeChange = (e) => classifyPath(e.file) === 'code' && !isCommentOnlyChange(e);

export const BUILTIN_MERGE_RULES = new Map([
  ['doc-changes', {
    appliesTo: (e) => changeKindOf(e) !== 'deleted' && classifyPath(e.file) === 'doc',
  }],
  ['readme-changes', {
    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).toLowerCase() === 'readme.md',
  }],
  ['comment-only-changes', {
    appliesTo: isCommentOnlyChange,
  }],
  // Every change kind, a deletion included: a policy naming this class predicted
  // the test tree as the change's shape, and a test file removed or renamed
  // inside that tree is that same shape — a rename lands as a delete beside an
  // add, and parking it asked a reviewer for a decision nobody made.
  ['test-changes', {
    appliesTo: (e) => classifyPath(e.file) === 'test',
  }],
  ['markdown-line-removals', {
    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
      && changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after),
  }],
  // The trim superset of the rule above: whole-line removals plus in-line trims
  // (trimsOnly) — for a prune allowed to cut a line down, never to grow one.
  ['markdown-trims', {
    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
      && changeKindOf(e) !== 'added' && trimsOnly(e.before, e.after),
  }],
  ['file-additions', {
    appliesTo: (e) => changeKindOf(e) === 'added',
  }],
  ['generated-file-changes', {
    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).includes('GENERATED'),
  }],
  // The language-scoped class, matching ANY change to a JavaScript-family file —
  // built in mostly for its `reject:` use ("nothing may touch the JS"), which is
  // why it applies to every change kind. Its file set is the checks engine's own
  // JavaScript class, so the two surfaces cannot disagree on what counts.
  ['javascript-changes', {
    appliesTo: (e) => FILE_CLASSES.javascriptFiles.test(e.file),
  }],
  ['single-file-code-changes', {
    appliesTo: isRealCodeChange,
    constraint: (covered) => {
      const files = [...new Set(covered.map((e) => e.file))].sort();
      return files.length <= 1 ? null : `code changed in ${files.length} files: ${files.join(', ')}`;
    },
  }],
  ['single-folder-code-changes', {
    appliesTo: isRealCodeChange,
    constraint: (covered) => {
      const dirs = [...new Set(covered.map((e) => path.dirname(e.file)))].sort();
      return dirs.length <= 1 ? null : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`;
    },
  }],
]);

// Composites expand into their member allow terms — `narrow-diff` is the queue's
// historical `Merge: if-narrow` shape. Slightly stricter than the retired
// narrowVerdict on purpose: a DELETED doc is no longer silently allowed
// (deciding a document should not exist is a reviewed change — the
// improve-comments-scope lesson), which fails toward a parked PR, never a merge.
export const COMPOSITE_POLICIES = new Map([
  ['narrow-diff', ['doc-changes', 'test-changes', 'comment-only-changes', 'single-folder-code-changes']],
]);

// --- the inline path scope (`under:<dir>`) ------------------------------------

// A rule name that carries its own argument: `under:packs/claudinite-tasks`
// covers every change inside that directory. It exists because a scope is
// usually per-request — the one folder an ad-hoc ask or a task is confined to —
// where a named merge-rules.json rule is per-pack and costs a commit to add.
//
// It covers any change KIND inside the directory (added, modified, deleted):
// "any change under this folder" reads as literally any. And it scopes rather
// than widens — a changed file outside the folder is covered by no allow term,
// so a diff that strays parks — with POLICY_SOURCES below still absolute, so a
// folder scope cannot reach the files that define policies even when they sit
// inside it.
export const UNDER_PREFIX = 'under:';

const PATH_SEGMENT_RE = /^[A-Za-z0-9._-]+$/;

// The rule an `under:<dir>` term denotes, or null when `<dir>` is not a usable
// repo-relative directory (absolute, empty, or carrying a `.`/`..` segment).
// Null is a verdict: an unresolvable scope makes the whole policy invalid, which
// authorizes nothing — the same fail-closed answer an unknown rule name gets.
export function underRule(term) {
  const dir = term.slice(UNDER_PREFIX.length).replace(/\/+$/, '');
  const segments = dir.split('/');
  if (!dir || segments.some((seg) => !PATH_SEGMENT_RE.test(seg) || seg === '.' || seg === '..')) return null;
  const prefix = `${dir}/`;
  return { name: term, appliesTo: (e) => e.file.startsWith(prefix) };
}

// --- the `&&` intersection ----------------------------------------------------

// A policy list is a UNION: adding a term widens what may land. `&&` is the one
// narrowing operator — `under:product-wiki&&doc-changes` covers a file only when
// every part covers it, so it reads as "docs, and only under that folder".
//
// Whitespace around it is accepted wherever a human writes one (an issue's
// `Automerge:` line, a task declaration) and canonicalized away by
// `policyExpression`, so what rides the commit trailer stays one whitespace-free
// token. `&` is not a legal character in a rule name or an `under:` path, so the
// operator can never be read as part of a term.
export const CONJUNCTION = '&&';

const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());

// --- pack-declared rules (merge-rules.json) -----------------------------------

export const MERGE_RULES_FILE = 'merge-rules.json';

const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
const CHANGE_KINDS = ['added', 'modified', 'deleted'];
const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];

// Regex-as-string in the `/body/flags` form declared-checks.json already uses —
// the same inline parse pattern-rules.mjs applies (this module cannot import the
// checks engine's private compiler, so the six lines live here and point there).
function compileRegex(raw, where) {
  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
  return new RegExp(m[1], m[2]);
}

// One declared rule compiled into the registry shape. Every key is validated and
// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
// a matcher nobody decided (the corpus' explicit-over-default rule).
export function compileDeclaredRule(spec, where) {
  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
  }
  for (const key of Object.keys(spec)) {
    if (!DECLARED_KEYS.includes(key)) {
      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
    }
  }
  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
  }
  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
  const exclude = spec.excludePathMatching === undefined
    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
  }
  if (!EDIT_SHAPES.includes(spec.editShape)) {
    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
  }
  // The one key that may relax the self-widening guard, and only for files under
  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
  // saying "this task may rewrite the mount, policy definitions included" — the
  // adoption/converge grant. `true` only, so it cannot be half-declared.
  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
  }
  return {
    name: spec.name,
    coversMountPolicySources: spec.coversMountPolicySources === true,
    appliesTo(e) {
      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
      return true;
    },
  };
}

// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
// pack objects (each with `.dir`), `config` the normalized repo config — the pair
// both judging surfaces already hold. A broken declaration or a name collision is
// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
// closed, and the error text is what gets it fixed.
export function declaredMergeRules(packs, config) {
  const rules = new Map();
  const errors = [];
  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
    const file = path.join(pack.dir, MERGE_RULES_FILE);
    if (!existsSync(file)) continue;
    const where = `${pack.id}/${MERGE_RULES_FILE}`;
    let specs;
    try {
      specs = JSON.parse(readFileSync(file, 'utf8'));
      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
    } catch (e) {
      errors.push(`${where}: ${e.message}`);
      continue;
    }
    for (const spec of specs) {
      try {
        const rule = compileDeclaredRule(spec, where);
        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
        }
        rules.set(rule.name, rule);
      } catch (e) {
        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
      }
    }
  }
  return { rules, errors };
}

// --- policy parsing -----------------------------------------------------------

const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;

// A policy, normalized from any surface it rides — the declaration's string or
// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
// every consumer treats it as "authorizes nothing", loudly.
export function normalizePolicy(raw) {
  if (raw == null) return { kind: POLICY_NOTHING };
  const terms = Array.isArray(raw)
    ? raw.map((t) => String(t).trim())
    : String(raw).trim().split(';').map((t) => t.trim());
  if (terms.length === 1) {
    const one = terms[0].toLowerCase();
    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
    // The queue's historical spellings for its one pre-policy authorization.
    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
  }
  const allow = [];
  const reject = [];
  for (const term of terms) {
    const isReject = term.startsWith('reject:');
    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
    for (const part of parts) {
      if (!TERM_NAME_RE.test(part)) {
        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
      }
      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
      }
    }
    // A composite is itself a union, so intersecting one is ambiguous, and the
    // whole-policy words mean nothing narrowed: both are authoring errors.
    if (parts.length > 1) {
      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
      if (notIntersectable) {
        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
      }
    }
    const name = parts.join(CONJUNCTION);
    if (isReject) {
      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
      reject.push(name);
    } else if (name === POLICY_ANYTHING) {
      allow.push(name);
    } else if (name === POLICY_NOTHING) {
      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
    } else {
      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
    }
  }
  if (!allow.length) {
    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
  }
  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
}

// The string form of a declared policy — what rides the commit trailer and the
// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
// the one place whitespace around `&&` is collapsed, which is what keeps the
// stamped trailer a single whitespace-free token.
export const policyExpression = (policy) =>
  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
    .join(';');

// --- the verdict --------------------------------------------------------------

// The files no granular policy may cover except as comment-only edits: the
// sources the policy machinery itself is read from. Whatever an allow rule says,
// a run authorized by a list must not be able to rewrite what it is authorized
// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
// the mount refresh replaces these files wholesale, and that lane's trust is the
// repo's delivery setting, not a diff class.)
//
// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
// a declared rule carrying `coversMountPolicySources` — the shape an adoption
// re-vendor has, where policy files arrive canon-authored inside the pack trees
// it copies. The flag rides merge-rules.json, which is itself guarded and
// owner-committed, so a run cannot grant it to itself; repo-owned policy
// sources (everything outside the mount) stay absolute.
const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.json)$/;
const VENDORED_MOUNT = /^\.claudinite\/shared\//;

// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
// `errors` passed through so a broken declaration fails any policy that names
// the broken pack's rule set. Returns { mergeable, why, files, problems }:
// `files` carries one line per changed file (its covering rule, or its
// violation), `problems` each refusal as { file, what } — file null for a
// whole-diff refusal — because a run that parks has to say what it parked over.
export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
  const refuse = (problems, files = []) => ({
    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
  });
  const norm = normalizePolicy(policy);
  if (norm.kind === 'invalid') return refuse([{ file: null, what: `invalid policy: ${norm.reason}` }]);
  if (norm.kind === POLICY_NOTHING) {
    return refuse([{ file: null, what: 'the policy authorizes nothing to auto-merge' }]);
  }
  if (norm.kind === POLICY_ANYTHING) {
    return { mergeable: true, why: 'the policy authorizes any diff (the repo\'s delivery settings still apply)', files: [], problems: [] };
  }
  if (!entries.length) {
    return refuse([{ file: null, what: 'this branch changes nothing against the base — there is nothing to merge' }]);
  }

  const resolveOne = (name) => (name.startsWith(UNDER_PREFIX)
    ? underRule(name)
    : BUILTIN_MERGE_RULES.get(name) ?? declaredRules.get(name) ?? null);
  // An `&&` term is one rule that every part must agree on — for coverage and
  // for the whole-diff constraints alike. It deliberately carries no
  // `coversMountPolicySources`: that grant belongs to the declared rule that was
  // committed with it, never to an expression composed around it.
  const resolve = (name) => {
    if (!name.includes(CONJUNCTION)) return resolveOne(name);
    const parts = name.split(CONJUNCTION).map(resolveOne);
    if (parts.some((r) => !r)) return null;
    return {
      name,
      appliesTo: (e) => parts.every((r) => r.appliesTo(e)),
      constraint: (covered) => parts.map((r) => r.constraint?.(covered) ?? null).find(Boolean) ?? null,
    };
  };
  const unknown = [...norm.allow, ...norm.reject].filter((n) => n !== POLICY_ANYTHING && !resolve(n));
  if (unknown.length) {
    const errs = ruleErrors.length ? ` (rule declarations also failed to load: ${ruleErrors.join('; ')})` : '';
    return refuse([{ file: null, what: `unresolved rule name(s): ${unknown.join(', ')} — an unknown rule authorizes nothing${errs}` }]);
  }

  const files = [];
  const problems = [];
  const coveredBy = new Map(); // allow name -> entries it covered
  for (const entry of entries) {
    const { file } = entry;
    if (POLICY_SOURCES.test(file) && !isCommentOnlyChange(entry)) {
      const mountCoverer = VENDORED_MOUNT.test(file)
        && norm.allow.find((n) => resolve(n)?.coversMountPolicySources && resolve(n).appliesTo(entry));
      if (!mountCoverer) {
        files.push({ file, verdict: 'policy-source' });
        problems.push({ file, what: `${file} defines auto-merge policy itself — no granular policy may change it` });
        continue;
      }
      // Exempted: it falls through to the ordinary reject/coverage flow below,
      // so a reject term still vetoes it and the flagged rule still has to
      // cover it on its own terms.
    }
    const rejectedBy = norm.reject.find((n) => resolve(n).appliesTo(entry));
    if (rejectedBy) {
      files.push({ file, verdict: `rejected:${rejectedBy}` });
      problems.push({ file, what: `${file} matches reject:${rejectedBy}` });
      continue;
    }
    const coverer = norm.allow.find((n) => n === POLICY_ANYTHING || resolve(n).appliesTo(entry));
    if (coverer === undefined) {
      files.push({ file, verdict: 'uncovered' });
      problems.push({ file, what: `${file} (${changeKindOf(entry)} ${classifyPath(entry.file)}) is covered by no allow term` });
      continue;
    }
    files.push({ file, verdict: `covered:${coverer}` });
    if (!coveredBy.has(coverer)) coveredBy.set(coverer, []);
    coveredBy.get(coverer).push(entry);
  }
  for (const [name, covered] of coveredBy) {
    const failed = resolve(name)?.constraint?.(covered) ?? null;
    if (failed) problems.push({ file: null, what: `${name}: ${failed}` });
  }

  return problems.length
    ? refuse(problems, files)
    : { mergeable: true, why: `every changed file is covered (${[...coveredBy.keys()].join(', ')})`, files, problems: [] };
}

// --- the diff against a base ref (shared with narrow-diff.mjs) ----------------

// `stderr: ignore` because the ONE expected failure here — `git show` on a path
// that does not exist at that ref — is how an added or deleted file answers, and
// letting git narrate it once per such file buries the verdict the caller reads.

import { finding } from '../../../engine/checks/helpers/findings.mjs';
import {
  AUTOMERGE_TRAILER, AUTOMERGE_TRAILER_RE, policyVerdict, declaredMergeRules,
} from '../src/contract/merge-policy.mjs';

// The armed-auto-merge gate: when a branch says it intends to land itself under
// a granular policy, the diff must actually sit inside that policy — re-checked
// here, at the Stop hook and on every PR, so a run that mis-measured (or lied
// about) its own diff goes red before GitHub's queued auto-merge can fire.
//
// SELF-GATING BY THE TRAILER, the shape improve-comments-scope keys on its
// pinned commit subject: a landing run stamps `Claudinite-Automerge-Policy:
// <expr>` into its final commit message (deliver-pr.md owns when), so this rule
// runs everywhere the pack is active and costs ~nothing on a branch that armed
// nothing. No trailer, no findings — a wide PR left open for review must stay
// green, since red CI would get it closed as failed rather than read. The LAST
// trailer on the branch wins: a run that re-measured after amending its scope
// states its final intent last.
//
// The policy is re-evaluated from the trailer, not re-read from the task
// declaration, because the branch may BE the thing changing declarations; what
// keeps the trailer honest is the policy engine's own self-widening guard — no
// granular policy covers a change to the policy sources — plus the landing lane
// only merging on the same verdict this rule computes.
const rule = {
  id: 'automerge-policy-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/claudinite-tasks/README.md',
  description: 'A branch that stamps the Claudinite-Automerge-Policy trailer — its run intends to land its own PR — carries only a diff that policy actually covers',
  why: 'the trailer is a claim that this diff may merge with nobody looking; a diff outside the declared classes is exactly the unreviewed change the policy exists to stop, and only a check can hold the claim to the measurement',

  run(work) {
    if (work.onDefaultBranch()) return [];
    // work.commits is newest-first (git log order), so the newest commit's
    // trailer — the branch's final stated intent — is the first match.
    const armed = work.commits.map((m) => AUTOMERGE_TRAILER_RE.exec(m)?.[1]).find(Boolean);
    if (armed === undefined) return [];

    const deleted = new Set(work.deleted);
    const entries = [...new Set([...work.changedFiles, ...work.deleted])].sort().map((file) => ({
      file,
      before: work.readBase(file),
      after: deleted.has(file) ? null : work.read(file),
    }));
    const { rules, errors } = declaredMergeRules(work.packs, work.config);
    const verdict = policyVerdict({ policy: armed, entries, declaredRules: rules, ruleErrors: errors });
    if (verdict.mergeable) return [];

    return verdict.problems.map((p) => finding(rule, {
      file: p.file ?? '(branch)',
      what: `this branch armed auto-merge (${AUTOMERGE_TRAILER}: ${armed}) but ${p.what}`,
      fix: p.file
        ? `revert or split out ${p.file}, or drop the trailer from the branch's last commit and leave the PR for review — never widen the policy to fit the diff`
        : 'make the diff satisfy the armed policy, or drop the trailer and leave the PR for review',
    }));
  },
};

export default rule;

